primaryQuery:
run: order_items -> {
  group_by: user_id
  aggregate: orders is count(order_id)
} -> {
  aggregate:
    buyers is count()
    repeat_customers is count() { where: orders > 1 }
} -> {
  select:
    buyers
    repeat_customers
    repeat_rate is round(repeat_customers / buyers, 4)
}

verifyQuery:
run: users extend {
  join_many: oi is order_items on id = oi.user_id
} -> {
  group_by: id
  aggregate: orders is count(oi.order_id)
} -> {
  where: orders > 0
  aggregate: buyers is count(), single_buyers is count() { where: orders = 1 }
} -> {
  select:
    buyers
    repeat_customers is buyers - single_buyers
    repeat_rate is round((buyers - single_buyers) / buyers, 4)
}
